  ('Almancada "also" sözcüğü İngilizcedeki "also" (de, ayrıca) ile aynı yazılır. Almancada en yaygın anlamı hangisidir?', 'yani, öyleyse', ['de, dahi', 'her zaman, sürekli olarak', 'hemen'], 'Almanca "also" "yani, demek ki" anlamındadır; "de, ayrıca" anlamı "auch" ile verilir.'),
  ('Almancada "Kind" sözcüğü İngilizcedeki "kind" (nazik, tür) ile benzer görünür. Almancadaki anlamı hangisidir?', 'çocuk', ['nazik', 'tür, çeşit', 'akraba'], 'Almanca "das Kind" çocuk demektir.'),
  ('Almancada "Viel Glück!" ifadesi hangi durumda söylenir?', 'Sınava giren birine başarı dilerken', ['Biri hastalanınca geçmiş olsun derken', 'Birinin doğum gününü kutlarken', 'Yemekten sonra teşekkür ederken'], '"Viel Glück" bol şans demektir.'),
  ('Almanyada doğum günü kutlamasında söylenen kalıp hangisidir?', 'Alles Gute zum Geburtstag!', ['Gute Besserung!', 'Frohe Ostern!', 'Herzliches Beileid für Sie!'], '"Alles Gute zum Geburtstag" iyi ki doğdun demektir. "Gute Besserung" geçmiş olsun, "Frohe Ostern" mutlu Paskalyalar, "Gute Reise" iyi yolculuklardır.'),
  ('Almancada "Ich verstehe nicht" cümlesini kuran bir turist ne anlatmak istemektedir?', 'Anlamadığını', ['Duymadığını', 'Bilmediğini', 'Konuşamadığını'], '"Verstehen" anlamak demektir.'),
  ('Almancada "Herzlich willkommen!" ifadesi hangi durumda kullanılır?', 'Gelen konukları karşılarken', ['Bir yolcuyu uğurlarken', 'Birinden özür dilerken', 'Bir yemeği hiç beğenmediğini söylerken'], '"Willkommen" hoş geldiniz demektir; "herzlich" içtenlikle anlamını katar.'),
  ('Almanca "Kein Problem!" yanıtı hangi anlama gelir?', 'Sorun değil!', ['Hiç fikrim yok!', 'Bu çok zor!', 'Asla olmaz!'], '"Kein" hiç, "Problem" sorun demektir; ifade "sorun yok" anlamındadır.'),
  ('Almancada "kaufen" fiili hangi anlama gelir?', 'satın almak', ['satmak', 'ödünç vermek', 'takas etmek'], '"Kaufen" satın almak, "verkaufen" satmaktır.'),
  ('Almanca "verkaufen" fiili, "kaufen" fiiline "ver-" öneki getirilerek oluşur. Bu fiil ne anlama gelir?', 'satmak', ['satın almak', 'kiralamak', 'fiyat sormak'], '"Kaufen" satın almak, "verkaufen" satmak demektir; satıcı "Verkäufer"dir.'),
  ('Almancada "schlafen" fiilinin anlamı hangisidir?', 'uyumak', ['uyanmak', 'yıkanmak', 'giyinmek'], '"Schlafen" uyumak demektir; yatak odası "Schlafzimmer"dir.'),
  ('Almanca "Kannst du schwimmen?" sorusu neyi sorar?', 'Yüzme bilip bilmediğini', ['Koşmayı sevip sevmediğini', 'Bisiklet sürüp süremediğini', 'Dans etmeyi bilip bilmediğini'], '"Können" -ebilmek, "schwimmen" yüzmek demektir.'),
  ('Almanca "Mein Kopf tut weh" diyen birinin nesi ağrıyordur?', 'Başı', ['Karnı', 'Dişi', 'Sırtı'], '"Kopf" baş, "weh tun" ağrımak demektir. Karın "Bauch", diş "Zahn", sırt "Rücken"dir.'),
  ('Almancada "Auge", "Ohr" ve "Nase" sözcükleri sırasıyla hangi organları adlandırır?', 'göz, kulak, burun', ['kulak, göz, burun', 'burun, kulak, göz', 'göz, burun, ağız'], '"Auge" göz, "Ohr" kulak, "Nase" burundur.'),
  ('Almanca bir hava durumu bülteninde "Es regnet" deniyor. Dışarı çıkarken ne alınmalıdır?', 'Şemsiye', ['Güneş gözlüğü', 'Kayak takımı', 'Yelpaze'], '"Regnen" yağmur yağmak demektir; "Es regnet" yağmur yağıyor anlamındadır.'),
  ('Almancada "Es schneit" cümlesi hangi hava olayını anlatır?', 'Kar yağıyor.', ['Rüzgâr esiyor.', 'Güneş parlıyor.', 'Sis var.'], '"Schnee" kar, "schneien" kar yağmaktır.'),
  ('Almancada "kalt" ve "heiß" sıfatları sıcaklığı anlatır. Bunların Türkçe karşılıkları sırasıyla hangisidir?', 'soğuk, çok sıcak', ['ılık, serin', 'çok sıcak, soğuk', 'serin, ılık'], '"Kalt" soğuk, "heiß" çok sıcak, kızgın demektir; "warm" ılık/sıcaktır.'),
  ('Almancada "der Hund" ve "die Katze" sırasıyla hangi hayvanlardır?', 'köpek ve kedi', ['at ve inek', 'kedi ve köpek', 'kuş ve balık'], '"Hund" köpek, "Katze" kedidir.'),
  ('Bir Alman çiftliğinde "die Kuh", "das Pferd" ve "das Schwein" bulunuyor. Bu hayvanlar hangileridir?', 'inek, at, domuz', ['koyun, keçi, tavuk', 'at, inek, koyun', 'inek, eşek, ördek'], '"Kuh" inek, "Pferd" at, "Schwein" domuzdur.'),
  ('Almancada "die Schule" kelimesinin anlamı nedir?', 'okul', ['öğretmen', 'sınıf', 'ders kitabı'], '"Schule" okuldur; öğretmen "Lehrer", sınıf "Klasse"dir.'),
  ('Almanca "Der Lehrer schreibt an die Tafel" cümlesinde öğretmen nereye yazmaktadır?', 'Tahtaya', ['Defterine', 'Bilgisayara', 'Duvardaki ilana'], '"Tafel" okul tahtası demektir.'),
  ('Almancada "das Fenster" ve "die Tür" sırasıyla bir evin hangi bölümleridir?', 'pencere ve kapı', ['duvar ve çatı', 'merdiven ve balkon', 'kapı ve pencere'], '"Fenster" pencere, "Tür" kapıdır.'),
  ('Almanca "Ich bin Arzt" diyen bir kişinin mesleği nedir?', 'Doktor', ['Avukat', 'Mühendis', 'Mimar'], '"Arzt" doktor (hekim) demektir. Almancada meslek bildirilirken adın önüne artikel konmaz: Ich bin Arzt.'),
  ('Almanca bir iş ilanında "Koch gesucht" yazıyor. Hangi meslekten biri aranmaktadır?', 'Aşçı', ['Şoför', 'Muhasebeci', 'Bekçi'], '"Koch" aşçı, "gesucht" aranıyor demektir.'),
  ('Almanyada kışın dışarı çıkan biri "Mütze", "Schal" ve "Handschuhe" takıyor. Bunlar hangi giysilerdir?', 'bere, atkı, eldiven', ['şapka, kemer, çorap', 'bere, ceket, bot', 'atkı, kravat, eldiven'], '"Mütze" bere, "Schal" atkı, "Handschuhe" eldivenlerdir.'),
  ('Almancada "das Geld" sözcüğü neyi anlatır?', 'para', ['altın', 'fatura', 'cüzdan'], '"Geld" paradır; altın "Gold", cüzdan "Geldbörse"dir.'),
  ('Almancada "das Zimmer" sözcüğünün anlamı hangisidir?', 'oda', ['mutfak', 'bahçe', 'bodrum'], '"Zimmer" odadır; mutfak "Küche", bahçe "Garten"dır.'),
  ('Almancada "teuer" ve "billig" sıfatları fiyatla ilgilidir. Bunlar sırasıyla ne anlama gelir?', 'pahalı ve ucuz', ['ucuz ve pahalı', 'bedava ve indirimli', 'pahalı ve indirimli'], '"Teuer" pahalı, "billig" ucuzdur.'),
  ('Almanca "Ich bin müde" diyen birine ne önerilir?', 'Dinlenmesi', ['Bir şeyler yemesi', 'Su içmesi', 'Doktora gitmesi'], '"Müde" yorgun, uykulu demektir.'),
  ('Almancada "glücklich" ve "traurig" sözcükleri sırasıyla hangi duyguları anlatır?', 'mutlu ve üzgün', ['kızgın ve korkmuş', 'şaşkın ve sakin', 'üzgün ve mutlu'], '"Glücklich" mutlu, "traurig" üzgündür.'),
  ('Almancada "die Stadt" ve "das Dorf" hangi yerleşim birimleridir?', 'şehir ve köy', ['köy ve kasaba', 'başkent ve eyalet', 'mahalle ve sokak'], '"Stadt" şehir, "Dorf" köydür.'),
  ('Almanca "Ich gehe in die Bibliothek" diyen biri nereye gidiyordur?', 'Kütüphaneye', ['Kitap satan bir dükkâna', 'Müzeye', 'Kiliseye'], '"Bibliothek" kütüphanedir; kitapçı "Buchhandlung"dur.'),
  ('Almancada "der Baum" ve "die Blume" sözcükleri neyi anlatır?', 'ağaç ve çiçek', ['çiçek ve ot', 'orman ve tarla', 'yaprak ve dal'], '"Baum" ağaç, "Blume" çiçektir.'),
  ('Paris\'te akşam saat dokuzda bir lokantaya giren müşteri garsonu nasıl selamlar?', 'Bonsoir !', ['Bonjour matin !', 'Bonne nuit !', 'Au revoir !'], '"Bonsoir" akşam selamıdır. "Bonne nuit" yatmadan önce söylenen "iyi geceler"dir.'),
  ('Fransızca "Ça va ?" sorusuna verilen en doğal kısa yanıt hangisidir?', 'Ça va bien, merci.', ['Je m\'appelle Paul.', 'J\'ai vingt ans.', 'Il est midi.'], '"Ça va ?" "Nasıl gidiyor?" demektir; "İyi gidiyor, teşekkürler" uygun yanıttır.'),
  ('Fransızcada "Merci beaucoup" diyen birine kibarca verilen karşılık hangisidir?', 'De rien.', ['Pardon.', 'Bon appétit.', 'Enchanté.'], '"De rien" "bir şey değil, rica ederim" demektir.'),
  ('Fransızcada "s\'il vous plaît" ifadesinin Türkçe karşılığı hangisidir?', 'lütfen', ['teşekkürler', 'affedersiniz', 'hoş geldiniz'], '"S\'il vous plaît" sözcük olarak "eğer size hoş gelirse" demektir ve "lütfen" anlamında kullanılır.'),
  ('Fransızca "À bientôt !" ifadesi ne anlama gelir?', 'Yakında görüşürüz!', ['İyi geceler!', 'Hoş geldin!', 'Kolay gelsin, iyi çalışmalar!'], '"Bientôt" yakında demektir.'),
  ('Fransızca "Je m\'appelle Claire" cümlesi neyi bildirir?', 'Konuşanın adının Claire olduğunu', ['Konuşanın Claire\'i aradığını', 'Konuşanın Claire\'i tanıdığını', 'Konuşanın Claire\'in kardeşi olduğunu'], '"S\'appeler" adı ... olmak demektir; "Benim adım Claire".'),
  ('Fransızcada 70 sayısı "soixante-dix" diye söylenir. Bu adın yapısı nedir?', 'altmış + on', ['yedi + on', 'yedi kere on', 'seksen eksi on'], '"Soixante" 60, "dix" 10\'dur; 70 = 60+10 olarak söylenir.'),
  ('Fransızcada 80 sayısını anlatan "quatre-vingts" adı hangi işleme dayanır?', '4 × 20', ['40 × 2', '8 × 10', '60 + 20'], '"Quatre" 4, "vingt" 20\'dir; 80 = dört yirmi biçiminde söylenir.'),
  ('Fransızcada 1\'den 3\'e kadar sayılar sırasıyla nasıl söylenir?', 'un, deux, trois', ['une, dos, tres', 'eins, zwei, drei', 'un, trois, deux'], 'Fransızca: un (1), deux (2), trois (3). "Dos, tres" İspanyolca, "eins, zwei, drei" Almancadır.'),
  ('Fransızcada 100 sayısının karşılığı hangisidir?', 'cent', ['mille', 'dix', 'cinquante'], '"Cent" 100, "mille" 1000, "dix" 10, "cinquante" 50\'dir.'),
  ('Fransızcada "premier" ve "deuxième" sözcükleri neyi bildirir?', 'birinci ve ikinci', ['bir ve iki', 'yarım ve çeyrek', 'ilk ve son'], 'Bunlar sıra sayılarıdır: premier birinci, deuxième ikinci.'),
  ('Fransızcada "samedi" ve "dimanche" hangi günlerdir?', 'cumartesi ve pazar', ['cuma ve cumartesi', 'pazar ve pazartesi', 'perşembe ve cuma'], '"Samedi" cumartesi, "dimanche" pazardır.'),
  ('Fransızcada "l\'hiver" hangi mevsimdir?', 'Kış', ['Yaz', 'İlkbahar', 'Sonbahar'], '"L\'hiver" kış, "l\'été" yaz, "le printemps" ilkbahar, "l\'automne" sonbahardır.'),
  ('Fransızcada "la mère" ve "le père" sırasıyla hangi aile bireyleridir?', 'anne ve baba', ['baba ve anne', 'büyükanne ve dede', 'teyze ve amca'], '"Mère" anne, "père" babadır.'),
  ('Fransızca "Voici mon frère et ma sœur" diyen biri kimleri tanıtmaktadır?', 'Erkek ve kız kardeşini', ['Annesini ve babasını', 'Oğlunu ve kızını', 'Amcasını ve teyzesinin kızını'], '"Frère" erkek kardeş, "sœur" kız kardeştir.'),
  ('Fransızca "Je suis étudiant" cümlesinin anlamı nedir?', 'Ben öğrenciyim.', ['Ben öğretmenim.', 'Öğrenciyi takip ediyorum.', 'Öğrencilerim var.'], '"Je suis" ben -im, "étudiant" öğrencidir. ("Suivre" fiilinin çekimi de "je suis" olsa da burada "être" fiilidir.)'),
  ('Fransızcada "aller" fiili "Je vais à Paris" cümlesinde hangi anlamı taşır?', 'gitmek', ['gelmek', 'kalmak', 'dönmek'], '"Aller" gitmektir; "je vais" "gidiyorum" demektir.'),
  ('Fransızca bir tatil kartında "Il fait chaud et il y a du soleil" yazıyor. Hava nasıldır?', 'Sıcak ve güneşli', ['Soğuk ve karlı', 'Serin ve rüzgârlı', 'Yağmurlu ve bulutlu'], '"Chaud" sıcak, "soleil" güneştir.'),
  ('Bir Paris pazarında "C\'est combien ?" diye soran turist neyi öğrenmek ister?', 'Fiyatı', ['Ürünün nereden geldiğini', 'Pazarın kapanış saatini', 'Satıcının adını'], '"Combien" ne kadar, kaç demektir.'),
  ('Fransızca "Comment tu t\'appelles ?" sorusu neyi sorar?', 'Karşıdakinin adını', ['Karşıdakinin yaşını', 'Karşıdakinin telefon numarasını', 'Karşıdakinin nereli olduğunu'], '"Comment" nasıl, "s\'appeler" adı olmak demektir: "Adın ne?"'),
  ('Lyon\'da bir bankada çalışan memur, ilk kez gelen yaşlı bir müşteriye hangi zamirle hitap etmelidir?', 'vous', ['tu', 'il', 'on'], 'Tanımadık ve yaşça büyük kişilere saygı için "vous" kullanılır.'),
  ('Bir Fransız lokantasında hesabı istemek için ne söylenir?', 'L\'addition, s\'il vous plaît.', ['La carte, s\'il vous plaît.', 'Bon appétit, monsieur et madame.', 'Une table, s\'il vous plaît.'], '"L\'addition" hesaptır; "la carte" ise menüdür.'),
  ('Fransızca "C\'est délicieux !" diyen biri ne anlatmak istemektedir?', 'Yemeğin çok lezzetli olduğunu', ['Yemeğin fazla tuzlu olduğunu', 'Yemeğin soğuduğunu', 'Yemeğin fiyatının çok pahalı olduğunu'], '"Délicieux" nefis, lezzetli demektir.'),
  ('Fransa\'da bir fırında "une baguette" isteyen müşteri ne alır?', 'Uzun, ince bir ekmek', ['Ay biçiminde bir hamur işi', 'Çikolatalı bir pasta', 'Yuvarlak bir kek'], 'Baguette, ince ve uzun Fransız ekmeğidir; adı "çubuk" anlamına gelir.'),
  ('Fransızcada "h" harfi "hôtel" ve "homme" gibi sözcüklerde nasıl okunur?', 'Hiç okunmaz.', ['Türkçedeki "h" gibi okunur.', '"ş" gibi okunur.', '"k" gibi gırtlaktan okunur.'], 'Fransızcada "h" her zaman sessizdir: hôtel (otel), homme (om).'),
  ('Fransızca "Je ne comprends pas" diyen bir turist hangi sorunu dile getirmektedir?', 'Anlamadığını', ['Kaybolduğunu', 'Acıktığını', 'Yorulduğunu'], '"Comprendre" anlamak demektir; cümle "Anlamıyorum" anlamındadır.'),
  ('Fransızcada "Bon voyage !" ifadesi hangi durumda söylenir?', 'Yolculuğa çıkan birini uğurlarken', ['Yemeğe başlayan birine', 'Zor bir sınava girecek olan bir öğrenciye', 'Yeni bir eve taşınan birine'], '"Bon voyage" iyi yolculuklar demektir.'),
  ('Fransızca "Bonne chance !" ifadesi kime söylenir?', 'Bir işe girişecek ve şansa ihtiyacı olan birine', ['Hastaneden çıkan birine', 'Yemeğini bitiren birine', 'Yeni tanışılan birine, tokalaşırken'], '"Bonne chance" bol şans demektir.'),
  ('Fransızca "Où sont les toilettes ?" sorusu nerede sorulduğunda en doğaldır?', 'Bir lokantada ya da kafede', ['Bir futbol maçının ortasında sahada', 'Bir mektubun sonunda', 'Bir şarkının nakaratında'], 'Soru "Tuvaletler nerede?" demektir; kamuya açık bir mekânda sorulur.'),
  ('Fransızcada "Bienvenue !" sözcüğünün anlamı nedir?', 'Hoş geldiniz!', ['Güle güle!', 'Afiyet olsun!', 'Tebrikler!'], '"Bien" iyi, "venu" gelmiş demektir; ifade "hoş geldiniz"dir.'),
  ('Fransızca "Je suis fatigué" cümlesi ne anlatır?', 'Yorgunum.', ['Mutluyum.', 'Hastayım.', 'Kızgınım.'], '"Fatigué" yorgun demektir.'),
  ('İspanyolcada "Hola" sözcüğünün anlamı nedir?', 'Merhaba', ['Hoşça kal', 'Teşekkürler', 'Lütfen'], '"Hola" gün boyu kullanılabilen samimi bir selamdır.'),
  ('İspanyolca "¿Cómo estás?" sorusuna verilebilecek en uygun yanıt hangisidir?', 'Muy bien, gracias. ¿Y tú?', ['Me llamo Carlos, ¿y tú?', 'Tengo veinte años, gracias.', 'Soy de Sevilla, muy bien.'], 'Soru "Nasılsın?" demektir; "Çok iyiyim, teşekkürler. Ya sen?" yanıtı uygundur.'),
  ('İspanyolcada "Gracias" diyen birine verilen kibar yanıt hangisidir?', 'De nada.', ['Por favor.', 'Lo siento.', 'Buen provecho.'], '"De nada" rica ederim, bir şey değil demektir.'),
  ('İspanyolcada "Por favor" ifadesi hangi anlama gelir?', 'lütfen', ['teşekkür ederim', 'özür dilerim', 'hoş geldiniz'], '"Por favor" lütfen demektir.'),
  ('İspanyolca "Me llamo Lucía" cümlesi neyi bildirir?', 'Konuşanın adını', ['Konuşanın Lucía\'yı aradığını', 'Konuşanın Lucía\'yı çağırdığını', 'Konuşanın yaşını'], '"Llamarse" adı ... olmak demektir: "Benim adım Lucía".'),
  ('İspanyolca "¡Bienvenidos!" sözcüğü bir otel girişinde yazıyorsa ne anlama gelir?', 'Hoş geldiniz!', ['Güle güle, yine bekleriz!', 'İyi tatiller!', 'Dikkat, kaygan zemin!'], '"Bienvenido(s)" hoş geldin(iz) demektir.'),
  ('İspanyolcada "uno, dos, tres" sayılarından sonra gelen "cuatro" ve "cinco" hangi sayılardır?', '4 ve 5', ['5 ve 6', '3 ve 4', '4 ve 6'], 'Cuatro 4, cinco 5\'tir.'),
  ('İspanyolcada "mil" sözcüğü hangi sayıyı karşılar?', '1000', ['100', '1.000.000', '10'], '"Mil" bin, "cien" yüz, "millón" milyondur.'),
  ('İspanyolcada "¿Qué hora es?" sorusu neyi sorar?', 'Saatin kaç olduğunu', ['Bugünün hangi gün olduğunu', 'Kaç yaşında olunduğunu', 'Bir şeyin ne kadar tuttuğunu'], '"Hora" saat demektir; soru "Saat kaç?" anlamındadır.'),
  ('İspanyolca bir pazarda satıcı "Son diez euros" diyor. Müşteri ne kadar ödemelidir?', '10 avro', ['2 avro', '12 avro', '100 avro'], '"Diez" ondur; "dos" 2, "doce" 12, "cien" 100\'dür.'),
  ('İspanyolcada hafta sonu günleri olan "sábado" ve "domingo" hangileridir?', 'cumartesi ve pazar', ['cuma ve cumartesi', 'pazar ve pazartesi', 'perşembe ve cuma'], '"Sábado" cumartesi, "domingo" pazardır.'),
  ('İspanyolcada "agosto" hangi aydır?', 'Ağustos', ['Nisan', 'Ekim', 'Haziran'], '"Agosto" ağustostur; nisan "abril", ekim "octubre", haziran "junio"dur.'),
  ('İspanyolcada "la madre" ve "el padre" sırasıyla kimdir?', 'anne ve baba', ['baba ve anne', 'teyze ve amca', 'büyükanne ve dede'], '"Madre" anne, "padre" babadır.'),
  ('İspanyolcada "hermano" erkek kardeştir. "Tengo dos hermanas" diyen kişinin kaç kız kardeşi vardır?', '2', ['3', '1', '12'], '"Hermana" kız kardeş, çoğulu "hermanas"; "dos" ikidir.'),
  ('İspanyolca "La casa es blanca" cümlesinde ev hangi renktedir?', 'Beyaz', ['Siyah', 'Kahverengi', 'Gri'], '"Blanco/blanca" beyazdır; siyah "negro", gri "gris"tir.'),
  ('İspanyolcada "grande" ve "pequeño" sıfatları sırasıyla ne anlama gelir?', 'büyük ve küçük', ['küçük ve büyük', 'uzun ve kısa', 'yaşlı ve genç'], '"Grande" büyük, "pequeño" küçüktür.'),
  ('İspanyolcada "el libro" sözcüğünün çoğulu hangisidir?', 'los libros', ['las libros', 'el libros', 'los libroes'], 'Ünlüyle biten adlar "-s" alır; eril çoğul artikel "los"tur.'),
  ('İspanyolcada "un" ve "una" artikellerinin anlamı nedir?', 'bir (belirsiz artikel)', ['o (belirli artikel)', 'bu, şu (gösterme sıfatları)', 'hiç (olumsuzluk)'], '"Un" eril, "una" dişil belirsiz artikeldir.'),
  ('İspanyolca yazımda soru ve ünlem cümlelerinin başına konan ters işaretler hangileridir?', '¿ ve ¡', ['« ve »', '‹ ve ›', '; ve :'], 'İspanyolcada soru "¿...?" ve ünlem "¡...!" biçiminde iki işaretle yazılır.'),
  ('İspanyolca bir dükkânda "¿Cuánto cuesta?" diye soran biri neyi öğrenmek ister?', 'Fiyatı', ['Mağazanın adresini', 'Kaç tane kaldığını', 'Ürünün markasını'], '"Cuánto" ne kadar, "costar" tutmak demektir.'),
  ('İspanyolcada "¿Quién es?" sorusu kapıyı çalan birine sorulduğunda ne anlama gelir?', 'Kim o?', ['Ne istiyorsunuz?', 'Saat kaç?', 'Nereden geliyorsunuz?'], '"Quién" kim demektir.'),
  ('Sevilla\'da bir otel resepsiyonunda çalışan görevli, yaşlı bir konuğa nasıl hitap etmelidir?', 'usted', ['tú', 'vosotros', 'nosotros'], 'Resmî ve saygılı hitap "usted" ile yapılır.'),
  ('İspanyolcada "nosotros" zamiri hangi kişiyi anlatır?', 'biz', ['siz', 'onlar', 'ben'], '"Nosotros" biz, "vosotros" siz, "ellos" onlardır.'),
  ('İspanyolca "Me gusta el chocolate" cümlesinin anlamı nedir?', 'Çikolatayı severim.', ['Çikolata yerim.', 'Çikolatayı sevmem.', 'Çikolata isterim.'], '"Gustar" sözcük olarak "hoşa gitmek" demektir: "Çikolata bana hoş gelir".'),
  ('İspanya\'da bir barda küçük tabaklarda servis edilen atıştırmalıklara ne ad verilir?', 'tapas', ['tacos', 'pizzas', 'sushis'], 'Tapas, İspanyol mutfağına özgü küçük porsiyonlu atıştırmalıklardır.'),
  ('İspanyolca bir lokantada hesabı istemek için garsona ne söylenir?', 'La cuenta, por favor.', ['La carta, por favor.', 'Una mesa, por favor.', 'Buen provecho, señor.'], '"La cuenta" hesap; "la carta" menüdür.'),
  ('İspanyolcadaki "ñ" harfi, örneğin "España" sözcüğünde, nasıl okunur?', '"ny"', ['"n"', '"ng"', '"nn"'], '"Ñ" damaksıl bir "ny" sesidir: España (espanya).'),
  ('İspanyolcada "h" harfi "hola" ve "hotel" gibi sözcüklerde nasıl okunur?', 'Okunmaz.', ['Türkçedeki "h" gibi', 'Türkçedeki "ç" gibi', 'Türkçedeki "k" gibi'], 'İspanyolcada "h" sessizdir: hola (ola).'),
  ('İspanyolca "¿Dónde está la estación de tren?" sorusunu soran turist neyi aramaktadır?', 'Tren istasyonunu', ['Otobüs durağını', 'Havalimanını', 'Limanı'], '"Estación de tren" tren istasyonudur.'),
  ('İspanyolcada "el aeropuerto" sözcüğü "aero" (hava) ve "puerto" (liman) öğelerinden oluşur. Bu yer neresidir?', 'Havalimanı', ['Rüzgâr santrali', 'Deniz feneri', 'Uzay istasyonu'], 'Havalimanı İspanyolcada "aeropuerto"dur.'),
  ('İspanyolca bir binanın kapısında "Salida" yazıyor. Bu levha neyi gösterir?', 'Çıkışı', ['Girişi', 'Asansörü', 'Danışmayı'], '"Salida" çıkış, "entrada" giriştir.'),
  ('İspanyolcada "el perro" ve "el gato" sırasıyla hangi hayvanlardır?', 'köpek ve kedi', ['kedi ve köpek', 'at ve inek', 'kuş ve fare'], '"Perro" köpek, "gato" kedidir.'),
  ('İspanyolca "Soy médico y trabajo en un hospital" diyen kişinin mesleği nedir?', 'Doktor', ['Hemşire', 'Eczacı', 'Hastane müdürü'], '"Médico" doktordur.'),
  ('İspanyolcada "la playa" ve "el mar" sözcükleri hangi yerleri anlatır?', 'plaj ve deniz', ['dağ ve göl', 'nehir ve orman', 'ada ve körfez'], '"Playa" plaj, "mar" denizdir.'),
  ('İspanyolcada "comer" fiilinin anlamı nedir?', 'yemek yemek', ['içmek', 'pişirmek', 'satın almak'], '"Comer" yemek; içmek "beber", pişirmek "cocinar"dır.'),
  ('İspanyolca "Vivo en Valencia" cümlesinin anlamı nedir?', 'Valensiya\'da yaşıyorum.', ['Valensiya\'ya gidiyorum.', 'Valensiya\'yı seviyorum.', 'Valensiya\'dan geldim.'], '"Vivir" yaşamak demektir.'),
  ('İspanyolca "No sé" diyen biri ne söylemektedir?', 'Bilmiyorum.', ['Görmüyorum.', 'İstemiyorum.', 'Sevmiyorum.'], '"Saber" bilmek; "yo sé" biliyorum, "no sé" bilmiyorum demektir.'),
