  ('"Hayır" sözcüğünün Almanca, Fransızca ve İspanyolca karşılıkları sırasıyla hangisidir?', 'nein – non – no', ['non – nein – no', 'no – non – nein', 'nein – no – non'], 'Almanca "nein", Fransızca "non", İspanyolca "no".'),
  ('Almanca "Nacht", Fransızca "nuit" ve İspanyolca "noche" sözcüklerinin anlamı nedir?', 'gece', ['akşam', 'gün', 'sabah'], 'Üçü de "gece" demektir ve Hint-Avrupa ortak kökünden gelir.'),
  ('Fransızca "le chat", İspanyolca "el gato" ve Almanca "die Katze" sözcükleri hangi hayvanı anlatır?', 'kedi', ['köpek', 'fare', 'tavşan'], 'Üçü de kedi anlamındadır.'),
  ('Almancada "Freund", Fransızcada "ami", İspanyolcada "amigo" sözcüklerinin ortak anlamı nedir?', 'arkadaş, dost', ['düşman', 'komşu', 'uzak akraba'], 'Üçü de "arkadaş" demektir; ami ve amigo Latince "amicus"tan gelir.'),
  ('Almanca "Hund", Fransızca "chien" ve İspanyolca "perro" sözcüklerinin ortak anlamı nedir?', 'köpek', ['kurt', 'at', 'tilki'], 'Üçü de köpek demektir.'),
  ('Almancada "Ich", Fransızcada "je", İspanyolcada "yo" zamirleri hangi kişiyi gösterir?', 'ben', ['sen', 'o', 'biz'], 'Üçü de birinci tekil kişi zamiri "ben"dir.'),
  ('Fransızca "J\'aime le chocolat" cümlesinde "aimer" fiili hangi anlamı taşır?', 'sevmek', ['yemek', 'istemek', 'almak'], '"Aimer" sevmek, hoşlanmaktır.'),
  ('Almancada "Deutsch", Fransızcada "français", İspanyolcada "español" sözcükleri neyi anlatır?', 'Her dilin kendi adını', ['Her ülkenin başkentini', 'Her ülkenin parasını', 'Her dilde "merhaba" sözcüğünü'], 'Deutsch Almanca, français Fransızca, español İspanyolcadır; her biri dilin kendi adıdır.'),
  ('Almanların kendi ülkelerine verdikleri ad hangisidir?', 'Deutschland', ['Germania', 'Allemagne', 'Alemania'], 'Almanlar ülkelerini "Deutschland" diye adlandırır.'),
  ('İspanyolcada "España", Fransızcada "France" ve Almancada "Deutschland" adları neyi gösterir?', 'Her dilin konuşulduğu ana ülkenin kendi adını', ['Bu ülkelerin başkentlerini', 'Bu ülkelerin para birimlerini', 'Bu dillerin alfabelerini'], 'España İspanya, France Fransa, Deutschland Almanya\'nın kendi dillerindeki adlarıdır.'),
  ('Fransızca "Parlez-vous anglais ?" sorusu bir turist tarafından ne amaçla sorulur?', 'Karşısındakinin İngilizce bilip bilmediğini öğrenmek için', ['İngiltere\'ye nasıl gidileceğini öğrenmek için', 'İngilizce bir kitap satın almak için', 'Bir İngiliz\'i tanıyıp tanımadığını sormak için'], '"Parler" konuşmak, "anglais" İngilizcedir: "İngilizce konuşuyor musunuz?"'),
  ('Almancada "kommen" fiili "Ich komme aus der Türkei" cümlesinde neyi bildirir?', 'Konuşanın memleketini', ['Konuşanın gideceği yeri', 'Konuşanın Türkiye\'yi sevdiğini', 'Konuşanın Türkiye\'de yaşadığını'], '"Kommen aus" -den gelmek, -li olmak demektir.'),
  ('Almancada "machen" fiili "Hausaufgaben machen" ifadesinde hangi anlamı taşır?', 'yapmak', ['unutmak', 'kaybetmek', 'yazdırmak'], '"Machen" yapmaktır; "Hausaufgaben" ev ödevidir.'),
  ('Almanca "Kannst du mir helfen?" diye soran biri ne istemektedir?', 'Yardım', ['Para', 'Yol tarifi', 'Bir kalem'], '"Helfen" yardım etmek demektir.'),
  ('İspanyolca "¡Feliz cumpleaños!" ifadesi hangi durumda söylenir?', 'Birinin doğum gününde', ['Yeni yıl gecesinde', 'Bir düğünde', 'Bir mezuniyet töreninde'], '"Cumpleaños" doğum günü, "feliz" mutlu demektir.'),
  ('İspanyolca "¡Buena suerte!" ifadesinin anlamı nedir?', 'İyi şanslar!', ['İyi geceler!', 'İyi yolculuklar!', 'Afiyet olsun!'], '"Suerte" şans demektir.'),
  ('İspanyolca "No entiendo" diyen bir turist ne anlatmak istemektedir?', 'Anlamadığını', ['Duymadığını', 'Yorulduğunu', 'Kaybolduğunu'], '"Entender" anlamak demektir.'),
  ('Almancada "Brot", Fransızcada "pain", İspanyolcada "pan" diye söylenen besin hangisidir?', 'ekmek', ['peynir', 'pasta', 'pirinç'], 'Üç sözcük de ekmektir; pain ve pan Latince "panis"ten gelir.'),
  ('Bir gezgin üç ülkede "Hoşça kal" diyor: Almanya\'da "Tschüss", Fransa\'da "Au revoir". İspanya\'da en yaygın vedalaşma sözcüğü hangisidir?', 'Adiós', ['Hola', 'Gracias', 'Bienvenido'], 'İspanyolcada "Adiós" hoşça kal demektir; "Hola" merhabadır.'),
